.cm-export{--cm-fg:#cccccc;--cm-bg:#0c0c0c;--cm-chrome:#2b2b2b;--cm-chrome-fg:#a8a8a8;--cm-desk:#3a3a3f;color-scheme:dark}
.cm-export{display:inline-block}
.cm-export .cm-window{display:inline-block;border-radius:10px;overflow:hidden;box-shadow:0 10px 30px rgba(0,0,0,.35),0 0 0 1px rgba(127,127,127,.25);background:var(--cm-bg)}
.cm-export .cm-titlebar{position:relative;height:30px;line-height:30px;background:var(--cm-chrome);color:var(--cm-chrome-fg);font:13px system-ui,-apple-system,'Segoe UI',sans-serif;text-align:center}
.cm-export .cm-dots{position:absolute;left:12px;top:0}
.cm-export .cm-dots i{display:inline-block;width:12px;height:12px;border-radius:50%;margin-right:8px;vertical-align:middle;background:#ff5f57}
.cm-export .cm-dots i+i{background:#febc2e}
.cm-export .cm-dots i+i+i{background:#28c840}
.cm-export .cm-screen{display:block;box-sizing:content-box;margin:0;padding:12px;width:64ch;font-family:'Cascadia Mono', 'Cascadia Code', 'DejaVu Sans Mono', Menlo, Consolas, 'Liberation Mono', 'Courier New', monospace;font-size:14px;line-height:16.8px;color:var(--cm-fg);background:var(--cm-bg);white-space:pre;overflow:hidden;font-variant-ligatures:none;font-kerning:none;-webkit-text-size-adjust:none;text-size-adjust:none;tab-size:1}
.cm-export .cm-screen span,.cm-export .cm-screen a{display:inline-block;vertical-align:top;height:16.8px}
.cm-export .cm-screen a{color:inherit;text-decoration:none}
.cm-export .cm-screen a:hover{text-decoration:underline}
.cm-export .cm-screen .n{width:1ch;text-align:center;overflow:visible}
.cm-export .cm-screen .w{width:2ch;text-align:center;overflow:visible}
.cm-export .s0{color:#e2e8f0;background:#1f2a3c;}
.cm-export .s1{color:#93c5fd;background:#1f2a3c;font-weight:bold;}
.cm-export .s2{color:#71717a;}
.cm-export .s3{color:#8b8f9a;}
.cm-export .s4{color:#4b5060;}
